"use client"

import React, { useState } from "react"
import { Link, cn } from "@heroui/react"
import { SealCheckIcon } from "@phosphor-icons/react"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { getTimeAgoLabel, getTimeAgoMessage } from "@/modules/dayjs"
import { pathConfig } from "@/resources/path"
import { EntityLink } from "@/components/blocks/feed/EntityLink"
import { UserAvatar } from "@/components/blocks/identity/UserAvatar"
import { ReactionBar } from "./ReactionBar"
import { CommentComposer } from "./CommentComposer"
import { ReactionType, type CommentNode } from "@/modules/api/graphql/queries/types/discussion"
/** Callbacks shared down the comment tree. */
export interface CommentItemCallbacks {
    /** Post a reply under `parentId`. */
    onReply: (parentId: string, body: string) => void
    /** Edit a comment body (author only). */
    onEdit: (commentId: string, body: string) => void
    /** Soft-delete a comment (author only). */
    onDelete: (commentId: string) => void
    /** React to a comment (null removes the reaction). */
    onReactComment: (commentId: string, type: ReactionType | null) => void
    /** Lazily load the replies of `parentId`. */
    onLoadReplies: (parentId: string) => void
}

/** Props for {@link CommentItem}. */
export interface CommentItemProps extends CommentItemCallbacks {
    /** The comment to render. */
    comment: CommentNode
    /** Current viewer id (drives owner-only actions); null when unknown. */
    currentUserId: string | null
    /** Nesting depth (controls visual indentation). */
    depth: number
    /** Replies keyed by parent comment id (lazily populated by the container). */
    repliesByParent: Record<string, Array<CommentNode>>
}

/**
 * A single threaded comment with author, reactions, owner actions, reply box, and its
 * recursively-rendered replies. Visual indentation is capped so deep threads stay readable.
 *
 * Presentational: owns only transient UI state (editing/replying/expanded); persistence is
 * delegated via the {@link CommentItemCallbacks}.
 * @param props - {@link CommentItemProps}
 */
export const CommentItem = ({
    comment,
    currentUserId,
    depth,
    repliesByParent,
    onReply,
    onEdit,
    onDelete,
    onReactComment,
    onLoadReplies}: CommentItemProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    // transient per-comment UI state
    const [replying, setReplying] = useState(false)
    const [editing, setEditing] = useState(false)
    const [expanded, setExpanded] = useState(false)

    const isOwner = currentUserId !== null && currentUserId === comment.author.id
    const replies = repliesByParent[comment.id] ?? []

    // expand/collapse the reply subtree, loading it on first expand
    const toggleReplies = () => {
        const next = !expanded
        setExpanded(next)
        if (next) {
            onLoadReplies(comment.id)
        }
    }

    return (
        <div
            className={cn("flex flex-col gap-2",
                // indent nested replies with a guide border, capped after a few levels
                depth > 0 ? "border-l border-default pl-3 @app-sm:pl-4" : undefined)}
        >
            <div className="flex gap-3">
                <UserAvatar
                    size="sm"
                    username={comment.author.username}
                    avatar={comment.author.avatar}
                    className="mt-0 shrink-0"
                />
                <div className="flex min-w-0 flex-1 flex-col gap-2">
                    {/* author + founder badge + timestamp header */}
                    <div className="flex flex-wrap items-center gap-2">
                        <EntityLink
                            label={comment.author.username}
                            onPress={() => router.push(
                                pathConfig().locale(locale).profile(comment.author.username).build(),
                            )}
                        />
                        {comment.isFounderAuthor ? (
                            <SealCheckIcon
                                weight="fill"
                                aria-label={t("discussion.founderBadge")}
                                className="size-3.5 shrink-0 text-accent-soft-foreground"
                            />
                        ) : null}
                        <span className="text-xs text-muted">
                            {getTimeAgoLabel(getTimeAgoMessage(comment.createdAt), t)}
                        </span>
                        {comment.editedAt ? (
                            <span className="text-xs text-muted">{t("discussion.edited")}</span>
                        ) : null}
                    </div>

                    {/* body, edit form, or deleted placeholder */}
                    {comment.isDeleted ? (
                        <div className="text-sm italic text-muted">{t("discussion.deletedPlaceholder")}</div>
                    ) : editing ? (
                        <CommentComposer
                            initialValue={comment.body}
                            submitLabel={t("common.save")}
                            onCancel={() => setEditing(false)}
                            onSubmit={(body) => {
                                onEdit(comment.id, body)
                                setEditing(false)
                            }}
                        />
                    ) : (
                        <div className="whitespace-pre-wrap text-sm leading-relaxed text-foreground">
                            {comment.body}
                        </div>
                    )}

                    {/* action row: reactions + reply + owner edit/delete */}
                    {!comment.isDeleted && !editing ? (
                        <div className="flex flex-wrap items-center gap-3">
                            <ReactionBar
                                summary={comment.reactions}
                                onReact={(type) => onReactComment(comment.id, type)}
                            />
                            <Link
                                className="cursor-pointer text-xs font-medium text-muted hover:text-foreground"
                                onPress={() => setReplying((prev) => !prev)}
                            >
                                {t("discussion.reply")}
                            </Link>
                            {isOwner ? (
                                <>
                                    <Link
                                        className="cursor-pointer text-xs font-medium text-muted hover:text-foreground"
                                        onPress={() => setEditing(true)}
                                    >
                                        {t("common.edit")}
                                    </Link>
                                    <Link
                                        className="cursor-pointer text-xs font-medium text-muted hover:text-danger-soft-foreground"
                                        onPress={() => onDelete(comment.id)}
                                    >
                                        {t("common.delete")}
                                    </Link>
                                </>
                            ) : null}
                        </div>
                    ) : null}

                    {/* reply composer */}
                    {replying ? (
                        <CommentComposer
                            placeholder={t("discussion.replyPlaceholder")}
                            submitLabel={t("discussion.reply")}
                            onCancel={() => setReplying(false)}
                            onSubmit={(body) => {
                                onReply(comment.id, body)
                                setReplying(false)
                                // surface the new reply immediately by expanding the subtree
                                setExpanded(true)
                                onLoadReplies(comment.id)
                            }}
                        />
                    ) : null}

                    {/* replies toggle + recursive subtree */}
                    {comment.replyCount > 0 ? (
                        <Link
                            className="cursor-pointer self-start text-xs font-medium text-accent-soft-foreground hover:underline underline-offset-4 decoration-[var(--separator-tertiary)]"
                            onPress={toggleReplies}
                        >
                            {expanded
                                ? t("discussion.hideReplies")
                                : t("discussion.viewReplies", { count: comment.replyCount })}
                        </Link>
                    ) : null}

                    {expanded && replies.length > 0 ? (
                        <div className="mt-1 flex flex-col gap-3">
                            {replies.map((reply) => (
                                <CommentItem
                                    key={reply.id}
                                    comment={reply}
                                    currentUserId={currentUserId}
                                    depth={depth + 1}
                                    repliesByParent={repliesByParent}
                                    onReply={onReply}
                                    onEdit={onEdit}
                                    onDelete={onDelete}
                                    onReactComment={onReactComment}
                                    onLoadReplies={onLoadReplies}
                                />
                            ))}
                        </div>
                    ) : null}
                </div>
            </div>
        </div>
    )
}

"use client"

import React, { useMemo } from "react"
import { ChatsCircleIcon } from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { Button } from "@/components/atoms/buttons/Button"
import { Spinner } from "@/components/atoms/display/Spinner"
import { Typography } from "@/components/atoms/text/Typography"
import { AsyncContentEmpty } from "@/components/composites/async/AsyncContent"
import { StackV } from "@/components/frames/Stack"
import { CommentComposer } from "./CommentComposer"
import { CommentItem } from "./CommentItem"
import { ReactionType, type CommentNode } from "@/modules/api/graphql/queries/types/discussion"

export * from "./ReactionBar"
export * from "./ReactionEmoji"
export * from "./FacebookReactionSelector"
export * from "./CommentComposer"
export * from "./CommentItem"
export * from "./InteractionBar"
export * from "./constants"

/** Props for {@link Discussion}. */
export interface DiscussionProps {
    /** Current viewer id (drives owner-only actions); null when unknown. */
    currentUserId: string | null
    /** Current viewer identity for the composer avatar; null when signed out. */
    currentUser: { username: string, avatar?: string } | null
    /** Top-level comments for the content. */
    comments: Array<CommentNode>
    /** Total top-level comment count (for the heading). */
    total: number
    /** Whether the first page of comments is still loading. */
    isLoading: boolean
    /** Replies keyed by parent comment id (lazily populated). */
    repliesByParent: Record<string, Array<CommentNode>>
    /** Post a new top-level comment. */
    onSubmitComment: (body: string) => void
    /** Post a reply under a parent comment. */
    onReply: (parentId: string, body: string) => void
    /** Edit a comment body (author only). */
    onEdit: (commentId: string, body: string) => void
    /** Soft-delete a comment (author only). */
    onDelete: (commentId: string) => void
    /** React to a comment (null removes the reaction). */
    onReactComment: (commentId: string, type: ReactionType | null) => void
    /** Lazily load the replies of a parent comment. */
    onLoadReplies: (parentId: string) => void
    /** Whether more top-level comment pages remain to load. */
    hasMore?: boolean
    /** Whether the next page is currently loading. */
    isLoadingMore?: boolean
    /** Load the next page of top-level comments. */
    onLoadMore?: () => void
}

/**
 * Bottom-of-lesson discussion zone — FRAMELESS: a label ("Discussion · N") + an honest
 * "archive line" above an avatar-led composer and the threaded comment list, sitting
 * directly on the page canvas (no card). Mirrors Storybook `ContentDiscussion` shape
 * with house Typography / Stack / Button / Spinner.
 *
 * @param props - {@link DiscussionProps}
 */
export const Discussion = ({
    currentUserId,
    currentUser,
    comments,
    total,
    isLoading,
    repliesByParent,
    onSubmitComment,
    onReply,
    onEdit,
    onDelete,
    onReactComment,
    onLoadReplies,
    hasMore,
    isLoadingMore,
    onLoadMore,
}: DiscussionProps) => {
    const t = useTranslations()

    // real (not fabricated) count of currently-loaded top-level questions that already
    // have at least one reply — the "compounds over time" answer archive
    const answeredCount = useMemo(
        () => comments.filter((comment) => comment.replyCount > 0).length,
        [comments],
    )

    return (
        <StackV
            identity={{ tier: "block", component: "Discussion" }}
            gap={4}
            principle="group-boundary"
            explain="Header+composer group above the comment list — not sibling-stack, because these are section groups rather than repeating peers."
            items={[
                () => (
                    <StackV
                        gap={4}
                        principle="sibling-stack"
                        explain="Same-kind peer stack — not group-boundary, because label block and composer are repeating siblings in the header group."
                        items={[
                            () => (
                                <StackV
                                    gap={2}
                                    principle="title-subtitle"
                                    explain="Discussion title over its archive line — not sibling-stack, because the archive line is subordinate meta."
                                    items={[
                                        () => (
                                            <Typography
                                                weight="medium"
                                                text={t("discussion.title", { count: total })}
                                            />
                                        ),
                                        ...(total > 0 ? [() => (
                                            <Typography
                                                size="xs"
                                                color="muted"
                                                text={t("discussion.archiveLine", {
                                                    answered: answeredCount,
                                                    total,
                                                })}
                                            />
                                        )] : []),
                                    ]}
                                />
                            ),
                            () => (
                                <CommentComposer
                                    onSubmit={onSubmitComment}
                                    currentUser={currentUser}
                                    collapsible
                                />
                            ),
                        ]}
                    />
                ),
                ...(isLoading ? [() => (
                    <Spinner size="md" tone="accent" label={t("discussion.title", { count: total })} />
                )] : comments.length === 0 ? [() => (
                    <AsyncContentEmpty
                        icon={ChatsCircleIcon}
                        title={t("discussion.empty")}
                        description={t("discussion.emptyHint")}
                    />
                )] : [() => (
                    <StackV
                        gap={4}
                        principle="sibling-stack"
                        explain="Same-kind peer stack — not group-boundary, because comment rows are repeating siblings rather than section groups."
                        items={[
                            ...comments.map((comment) => () => (
                                <CommentItem
                                    key={comment.id}
                                    comment={comment}
                                    currentUserId={currentUserId}
                                    depth={0}
                                    repliesByParent={repliesByParent}
                                    onReply={onReply}
                                    onEdit={onEdit}
                                    onDelete={onDelete}
                                    onReactComment={onReactComment}
                                    onLoadReplies={onLoadReplies}
                                />
                            )),
                            ...(hasMore ? [() => (
                                <Button
                                    variant="ghost"
                                    size="sm"
                                    isDisabled={isLoadingMore}
                                    isPending={isLoadingMore}
                                    onPress={onLoadMore}
                                    label={t("discussion.loadMore")}
                                />
                            )] : []),
                        ]}
                    />
                )]),
            ]}
        />
    )
}

import React from "react"
import {
    ChatCircleIcon,
    PushPinIcon,
    SealCheckIcon,
} from "@phosphor-icons/react"
import { ReactionBar } from "../ReactionBar"
import { ReactionType } from "@/modules/api/graphql/queries/types/discussion"
import type { QueryCommunityFeedItemData } from "@/modules/api/graphql/queries/types/community-feed"
import { MarkdownContent } from "@/components/blocks/rendering/MarkdownContent"
import { Avatar } from "@/components/atoms/display/Avatar"
import { Typography } from "@/components/atoms/text/Typography"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { StackH, StackV } from "@/components/frames/Stack"
import { FillAvailable } from "@/components/frames/FillAvailable"

/** Props for {@link _CommunityPostCard} — presentational; labels already resolved. */
export interface CommunityPostCardProps {
    /** The post to render (author relation already loaded). */
    post: QueryCommunityFeedItemData
    /**
     * React handler — `(postId, emotion | null)`. Omit to render the reaction bar
     * READ-ONLY (e.g. when the viewer is signed out).
     */
    onReact?: (postId: string, type: ReactionType | null) => void
    /** Toggle the comment thread for this post. Omit to render the count static. */
    onToggleComments?: () => void
    /** Optional content rendered inside the card below the footer (e.g. comments). */
    children?: React.ReactNode
    /** Already-localized relative "x minutes ago" timestamp. */
    timeAgoLabel: string
    /** Already-localized channel name (e.g. "General"). */
    channelLabel: string
}

/**
 * One community feed post: author header (avatar + name + relative time + channel
 * + pinned badge), the markdown body, and a footer with the reaction bar + comment
 * count. Pure block: owns its look; the owning feature supplies data + the react
 * handler. Body renders via MarkdownContent (embedded flow) so inline code/markdown the
 * author wrote shows correctly.
 *
 * @param props - {@link CommunityPostCardProps}
 */
export const _CommunityPostCard = ({
    post,
    onReact,
    onToggleComments,
    children,
    timeAgoLabel,
    channelLabel,
}: CommunityPostCardProps) => {
    // resolve the display name, falling back to the username when unset
    const displayName = post.author.displayName || post.author.username

    return (
        <SurfaceCard
            identity={{ tier: "block", component: "CommunityPostCard" }}
            body={() => (
                <StackV
                    gap={4}
                    principle="sibling-stack"
                    explain="Same-kind peer stack — not group-boundary, because header, body, footer, and optional thread are repeating siblings in one post unit."
                    items={[
                        () => (
                            <StackH
                                gap={4}
                                principle="content-row"
                                explain="Keeps the author avatar and meta column on one baseline so the pin does not drop under the title."
                                align="center"
                                items={[
                                    () => (
                                        <Avatar
                                            src={post.author.avatar ?? undefined}
                                            name={displayName}
                                            seed={post.author.username}
                                        />
                                    ),
                                    () => (
                                        <FillAvailable
                                            at="base"
                                            body={() => (
                                                <StackV
                                                    gap={1}
                                                    principle="title-subtitle"
                                                    explain="Display name over handle/meta — not sibling-stack, because the meta line is subordinate rather than a peer action."
                                                    items={[
                                                        () => (
                                                            <StackH
                                                                gap={2}
                                                                principle="icon-text"
                                                                explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
                                                                align="center"
                                                                items={[
                                                                    () => (
                                                                        <Typography size="sm" weight="semibold" truncate text={displayName} />
                                                                    ),
                                                                    ...(post.isFounderAuthor ? [() => (
                                                                        <SealCheckIcon
                                                                            weight="fill"
                                                                            aria-hidden
                                                                            focusable="false"
                                                                            className="size-4 shrink-0 text-accent-soft-foreground"
                                                                        />
                                                                    )] : []),
                                                                ]}
                                                            />
                                                        ),
                                                        () => (
                                                            <StackH
                                                                gap={3}
                                                                principle="separator-dot"
                                                                explain="Places a middle-dot separator between short meta peers so the items read as one inline list."
                                                                align="center"
                                                                items={[
                                                                    () => (
                                                                        <Typography size="xs" color="muted" truncate text={`@${post.author.username}`} />
                                                                    ),
                                                                    () => (
                                                                        <Typography size="xs" color="muted" text={timeAgoLabel} />
                                                                    ),
                                                                    () => (
                                                                        <Typography size="xs" color="accent-soft" text={channelLabel} />
                                                                    ),
                                                                ]}
                                                            />
                                                        ),
                                                    ]}
                                                />
                                            )}
                                        />
                                    ),
                                    ...(post.isPinned ? [() => (
                                        <PushPinIcon
                                            weight="fill"
                                            aria-hidden
                                            focusable="false"
                                            className="size-4 shrink-0 text-accent-soft-foreground"
                                        />
                                    )] : []),
                                ]}
                            />
                        ),
                        () => (
                            <MarkdownContent markdown={post.body} flow="embedded" />
                        ),
                        () => (
                            <StackH
                                gap={6}
                                principle="flex-action"
                                explain="Reaction bar and comment toggle share one action row — not content-row, because both peers are controls rather than content-plus-meta."
                                align="center"
                                items={[
                                    () => (
                                        <ReactionBar
                                            count={post.reactions.total}
                                            myReaction={post.reactions.myReaction}
                                            onReact={onReact ? (type) => onReact(post.id, type) : undefined}
                                        />
                                    ),
                                    () => (
                                        <Typography
                                            size="xs"
                                            color="muted"
                                            isButton={Boolean(onToggleComments)}
                                            prefixIcon={ChatCircleIcon}
                                            text={String(post.commentCount)}
                                            onPress={onToggleComments}
                                        />
                                    ),
                                ]}
                            />
                        ),
                        ...(children ? [() => <>{children}</>] : []),
                    ]}
                />
            )}
        />
    )
}

import React from "react"
import type { ReactNode } from "react"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH, StackV } from "@/components/frames/Stack"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"

/** Props for {@link FeedItem}. */
export interface FeedItemProps {
    /**
     * Optional leading visual rendered at the row's start (e.g. a small
     * {@link UserAvatar} or an activity-type icon). Shrinks to its content and
     * never compresses the text column. Omit for a text-only row.
     */
    leading?: ReactNode
    /**
     * The activity / action text describing what happened. The caller is
     * responsible for localization (pass a `t()` result) and for mapping the
     * activity type to its phrasing.
     */
    children: ReactNode
    /**
     * Relative or absolute time the activity occurred, shown muted beneath the
     * action text. Caller-formatted (e.g. "2 hours ago").
     */
    timestamp: ReactNode
    /**
     * Optional footer rendered under the timestamp — e.g. a reaction bar. Omit for
     * a plain row.
     */
    footer?: ReactNode
}

/**
 * Generic activity / timeline row. Lays out an optional leading visual beside a
 * text column: the action text on top, a muted timestamp below, and an optional
 * footer (e.g. a reaction bar) beneath that.
 *
 * Purely presentational and self-contained — it holds no state and performs no
 * data access. The owning feature maps an activity type to the `leading` and
 * `children` content and passes a pre-formatted `timestamp`.
 *
 * @param props - {@link FeedItemProps}
 * @see Story: .storybook/stories/blocks/feed/FeedItem/FeedItem.stories
 */
export const FeedItem = ({ leading, children, timestamp, footer }: FeedItemProps) => {
    const textColumn: ComponentTypeWithSkeleton = () => (
        <StackV
            gap={2}
            principle="sibling-stack"
            explain="Same-kind peer stack — not group-boundary, because action text, timestamp, and optional footer are repeating vertical siblings in one row."
            items={[
                () => (
                    <StackV
                        gap={1}
                        principle="title-subtitle"
                        explain="Action line over its muted timestamp — not sibling-stack, because the timestamp is subordinate meta rather than a peer action."
                        items={[
                            () => <Typography size="sm" text={children} />,
                            () => <Typography size="xs" color="muted" text={timestamp} />,
                        ]}
                    />
                ),
                ...(footer ? [() => <>{footer}</>] : []),
            ]}
        />
    )

    if (!leading) {
        return (
            <StackV
                identity={{ tier: "block", component: "FeedItem" }}
                principle="sibling-stack"
                explain="Same-kind peer stack — not group-boundary, because this text-only feed row is a single vertical unit."
                items={[textColumn]}
            />
        )
    }

    return (
        <StackH
            identity={{ tier: "block", component: "FeedItem" }}
            gap={3}
            principle="content-row"
            explain="Keeps the leading visual and the action column on one baseline so the meta does not drop under the avatar."
            align="start"
            items={[
                () => <>{leading}</>,
                textColumn,
            ]}
        />
    )
}

"use client"

import React, {
    useCallback,
    useEffect,
    useRef,
    useState,
} from "react"
import useSWR from "swr"
import useSWRInfinite from "swr/infinite"
import { useLocale } from "next-intl"
import { useAppSelector } from "@/redux/hooks"
import { Discussion } from "@/components/blocks/community/Discussion"
import { GraphQLHeadersKey, type GraphQLHeaders } from "@/modules/api/graphql/types"
import { mutateCreateComment } from "@/modules/api/graphql/mutations/mutation-create-comment"
import { mutateDeleteComment } from "@/modules/api/graphql/mutations/mutation-delete-comment"
import { mutateReactToComment } from "@/modules/api/graphql/mutations/mutation-react-to-comment"
import { mutateUpdateComment } from "@/modules/api/graphql/mutations/mutation-update-comment"
import { queryContentComments } from "@/modules/api/graphql/queries/query-content-comments"
import { queryContentReactions } from "@/modules/api/graphql/queries/query-content-reactions"
import { ReactionType, type CommentNode } from "@/modules/api/graphql/queries/types/discussion"
import { contentDiscussionSocketIoEventEmitter } from "@/hooks/socketio/useContentDiscussionSocketIoLifecycle"
import { PublicationEvent } from "@/hooks/socketio/enums/publication-event"
import { SubscriptionEvent } from "@/hooks/socketio/enums/subscription-event"
import { useContentDiscussionSocketIo } from "@/hooks/socketio/useContentDiscussionSocketIo"
import { type SubscribeContentDiscussionSocketIoPayload } from "@/hooks/socketio/types/content-discussion"

/** Page size for a parent's replies (loaded in one shot per parent). */
const REPLIES_LIMIT = 50

/** Page size for the paginated top-level comment list ("load more"). */
const COMMENTS_PAGE_SIZE = 10

/** Server → client discussion events this container reacts to (revalidate on any). */
const DISCUSSION_EVENTS: ReadonlyArray<SubscriptionEvent> = [
    SubscriptionEvent.CommentCreated,
    SubscriptionEvent.CommentUpdated,
    SubscriptionEvent.CommentDeleted,
    SubscriptionEvent.ContentReactionChanged,
    SubscriptionEvent.CommentReactionChanged,
]

/**
 * Container for the lesson-content threaded comments.
 *
 * Owns the comment data hooks (local SWR), the realtime socket subscription (for BOTH
 * comment and reaction events), and all comment persistence callbacks; renders the
 * presentational {@link Discussion} (comments only — frameless). Rendered below the reading
 * card by {@link LessonReader}. The reaction picker itself lives in the reading-card footer
 * ({@link ContentReactionBar}); this container only keeps the reaction SWR alive so socket
 * events refresh that bar via the shared cache key. `"use client"` for hooks + socket.
 */
export const ContentDiscussion = () => {
    const locale = useLocale()
    const contentId = useAppSelector((state) => state.content.entity?.id)
    const currentUser = useAppSelector((state) => state.user.user)
    const currentUserId = currentUser?.id ?? null
    // the enrolled-guard on every discussion resolver requires the X-Course-Id header
    const courseId = useAppSelector((state) => state.course.entity?.id)
    const socket = useContentDiscussionSocketIo()

    // course header sent on every discussion call so GraphQLMustEnrolledGuard passes
    const courseHeaders: GraphQLHeaders | undefined = courseId
        ? {
            [GraphQLHeadersKey.XCourseId]: courseId,
        }
        : undefined

    // replies loaded on demand, keyed by parent comment id
    const [repliesByParent, setRepliesByParent] = useState<Record<string, Array<CommentNode>>>({})
    // track which parents have replies loaded so realtime can refresh exactly those
    const loadedParentsRef = useRef<Set<string>>(new Set())

    // content-level reaction summary — kept here ONLY to revalidate on realtime
    // ContentReactionChanged events; the reaction bar itself ({@link ContentReactionBar},
    // rendered in the reading-card footer) holds an SWR with this SAME key, so a
    // socket-driven mutate() here refreshes the bar through the shared cache.
    const reactionsSwr = useSWR(
        contentId && courseId ? ["content-discussion-reactions", contentId] : null,
        async () => {
            const response = await queryContentReactions({
                request: {
                    contentId: contentId as string,
                },
                headers: courseHeaders,
            })
            return response.data?.contentReactions.data
        },
    )

    // top-level comments, paginated for "load more"; each page is one API call
    const commentsSwr = useSWRInfinite(
        (pageIndex, previousPageData) => {
            // need both content + course (header) before any call (else the guard 400s)
            if (!contentId || !courseId) {
                return null
            }
            // stop paginating once a page comes back empty (reached the end)
            if (previousPageData && (previousPageData.comments?.length ?? 0) === 0) {
                return null
            }
            // 1-based page in the key tuple
            return ["content-discussion-comments", contentId, pageIndex + 1] as const
        },
        async ([, , page]) => {
            const response = await queryContentComments({
                request: {
                    contentId: contentId as string,
                    page,
                    limit: COMMENTS_PAGE_SIZE,
                },
                headers: courseHeaders,
            })
            return response.data?.contentComments.data
        },
    )

    // flatten loaded pages into a single comment list; total comes from the first page
    const commentPages = commentsSwr.data ?? []
    const comments = commentPages.flatMap((page) => page?.comments ?? [])
    const total = commentPages[0]?.total ?? 0
    // more remain while we have not yet accumulated the reported total
    const hasMore = comments.length < total
    // the last requested page is still resolving
    const isLoadingMore = commentsSwr.isValidating
        && commentsSwr.data !== undefined
        && typeof commentsSwr.data[commentsSwr.size - 1] === "undefined"

    // fetch a parent's replies and cache them in state
    const loadReplies = useCallback(async (parentId: string) => {
        if (!contentId || !courseId) {
            return
        }
        const response = await queryContentComments({
            request: {
                contentId,
                parentCommentId: parentId,
                limit: REPLIES_LIMIT,
            },
            headers: courseHeaders,
        })
        const replies = response.data?.contentComments.data?.comments ?? []
        // remember this parent so realtime updates can refresh it later
        loadedParentsRef.current.add(parentId)
        setRepliesByParent((prev) => ({
            ...prev,
            [parentId]: replies,
        }))
    }, [contentId, courseId, courseHeaders])

    // re-fetch every already-loaded reply subtree (used after a realtime event)
    const reloadLoadedReplies = useCallback(() => {
        loadedParentsRef.current.forEach((parentId) => {
            void loadReplies(parentId)
        })
    }, [loadReplies])

    // single revalidation entry point for any discussion change
    const revalidateAll = useCallback(() => {
        void reactionsSwr.mutate()
        void commentsSwr.mutate()
        reloadLoadedReplies()
    }, [reactionsSwr, commentsSwr, reloadLoadedReplies])

    // join the content's discussion room (and re-join on reconnect)
    useEffect(() => {
        if (!contentId || !courseId) {
            return
        }
        const subscribe = () => {
            const payload: SubscribeContentDiscussionSocketIoPayload = {
                data: {
                    contentId,
                },
                locale,
            }
            socket.emit(PublicationEvent.SubscribeContentDiscussion, payload)
        }
        // subscribe now if already connected, and again on every (re)connect
        if (socket.connected) {
            subscribe()
        }
        socket.on("connect", subscribe)
        return () => {
            socket.off("connect", subscribe)
        }
    }, [socket, contentId, courseId, locale])

    // refetch affected data whenever a realtime event arrives for this content
    useEffect(() => {
        if (!contentId || !courseId) {
            return
        }
        const handler = (message: { data?: { contentId?: string } }) => {
            // ignore events for other contents sharing the same socket
            if (message?.data?.contentId !== contentId) {
                return
            }
            revalidateAll()
        }
        DISCUSSION_EVENTS.forEach((event) => contentDiscussionSocketIoEventEmitter.on(event, handler))
        return () => {
            DISCUSSION_EVENTS.forEach((event) => contentDiscussionSocketIoEventEmitter.off(event, handler))
        }
    }, [contentId, courseId, revalidateAll])

    // --- persistence callbacks (optimistic-free: mutate then revalidate) ---

    const onSubmitComment = useCallback(async (body: string) => {
        if (!contentId || !courseId) {
            return
        }
        await mutateCreateComment({
            request: {
                contentId,
                body,
            },
            headers: courseHeaders,
        })
        void commentsSwr.mutate()
    }, [contentId, courseId, courseHeaders, commentsSwr])

    const onReply = useCallback(async (parentId: string, body: string) => {
        if (!contentId || !courseId) {
            return
        }
        await mutateCreateComment({
            request: {
                contentId,
                parentCommentId: parentId,
                body,
            },
            headers: courseHeaders,
        })
        // reply count + the subtree both changed
        void commentsSwr.mutate()
        void loadReplies(parentId)
    }, [contentId, courseId, courseHeaders, commentsSwr, loadReplies])

    const onEdit = useCallback(async (commentId: string, body: string) => {
        if (!courseId) {
            return
        }
        await mutateUpdateComment({
            request: {
                commentId,
                body,
            },
            headers: courseHeaders,
        })
        revalidateAll()
    }, [courseId, courseHeaders, revalidateAll])

    const onDelete = useCallback(async (commentId: string) => {
        if (!courseId) {
            return
        }
        await mutateDeleteComment({
            request: {
                commentId,
            },
            headers: courseHeaders,
        })
        revalidateAll()
    }, [courseId, courseHeaders, revalidateAll])

    const onReactComment = useCallback(async (commentId: string, type: ReactionType | null) => {
        if (!courseId) {
            return
        }
        await mutateReactToComment({
            request: {
                commentId,
                type,
            },
            headers: courseHeaders,
        })
        revalidateAll()
    }, [courseId, courseHeaders, revalidateAll])

    const onLoadReplies = useCallback((parentId: string) => {
        void loadReplies(parentId)
    }, [loadReplies])

    // hide the whole section until both content id and course id are available —
    // course id is required by the GraphQLMustEnrolledGuard on every discussion resolver
    if (!contentId || !courseId) {
        return null
    }

    return (
        <Discussion
            // discussion data
            currentUserId={currentUserId}
            currentUser={currentUser ? { username: currentUser.username, avatar: currentUser.avatar } : null}
            comments={comments}
            total={total}
            isLoading={commentsSwr.isLoading}
            repliesByParent={repliesByParent}
            onSubmitComment={onSubmitComment}
            onReply={onReply}
            onEdit={onEdit}
            onDelete={onDelete}
            onReactComment={onReactComment}
            onLoadReplies={onLoadReplies}
            hasMore={hasMore}
            isLoadingMore={isLoadingMore}
            onLoadMore={() => void commentsSwr.setSize(commentsSwr.size + 1)}
        />
    )
}

/** Folder-matching alias (export-matches-folder) — keep `ContentDiscussion` as the public name. */
export { ContentDiscussion as Discussion }
